// =====================================================================
function parseTargetNum(v) {
  if (v == null) return null;
  const s = String(v).trim();
  if (/^не\s/i.test(s)) return null;
  const m = s.match(/-?\d+(?:[.,]\d+)?/);
  return m ? parseFloat(m[0].replace(',', '.')) : null;
}
const todayMeals = meals.filter(m => m.Date && dkey(m.Date) === todayISO);
function sumCol(col) {
  return todayMeals.reduce((s, m) => s + (num(m[col]) || 0), 0);
}
