const BUDGET_KEYS = ['Насыщенные жиры', 'Добавленный сахар', 'Натрий', 'Кофеин', 'Клетчатка', 'Витамин D', 'Кальций'];
const budget = [];
for (const t of targets) {
  const name = t['Нутриент'];
  if (!BUDGET_KEYS.includes(name)) continue;
  const col = t['Колонка_в_Meals'];
  if (!col) continue;
  const isLimit = String(t['Категория'] || '').includes('Риск избытка');
  const rda = parseTargetNum(t['Норма_RDA_AI']);
  const ul  = parseTargetNum(t['Верхний_предел_UL']);
  const cap = isLimit ? ul : rda;
  if (!cap) continue;
  const consumed = Math.round(sumCol(col) * 100) / 100;
  const pct = Math.round((consumed / cap) * 100);
  budget.push({
    label: name, unit: t['Единица'] || '', kind: isLimit ? 'limit' : 'goal',
    consumed, cap, pct,
    remaining: Math.round((cap - consumed) * 100) / 100,
    status: isLimit ? (pct > 100 ? 'over' : pct >= 80 ? 'close' : 'ok')
                    : (pct >= 100 ? 'done' : pct >= 60 ? 'partial' : 'low'),
  });
}
budget.sort((a, b) => (a.kind === b.kind ? b.pct - a.pct : a.kind === 'limit' ? -1 : 1));

// протеин/калории за сегодня — из тех же Meals
const kcalToday = Math.round(sumCol('Calories'));
const protToday = Math.round(sumCol('Proteins'));

// =====================================================================
// 4. ПЛАН НЕДЕЛИ + отметки выполнения
// =====================================================================
// Без отметки «сделал» замер эффекта в «Что сработало» measures совпадение, а не эффект.
function actionId(issued, title) {
  return (issued || '') + '|' + String(title || '').slice(0, 60).replace(/\s+/g, ' ').trim();
}
const doneMap = {};
acts.forEach(a => {
  if (a.Action_ID) doneMap[String(a.Action_ID)] = String(a.Done || '').toLowerCase() === 'да'
    || String(a.Done || '').toLowerCase() === 'true' || a.Done === true;
});
const issued = latestRec ? dkey(latestRec.Date) : null;
const plan = {
  date: issued,
  actions: latestActions.map(a => ({
    id: actionId(issued, a.title),
    title: a.title, why: a.why || '', expect: a.expect || '',
    priority: a.priority || 'средний', metric: a.metric || null,
    done: !!doneMap[actionId(issued, a.title)],
  })),
};

