  .sort((a, b) => dkey(b.date).localeCompare(dkey(a.date)));
const ph = phenoValid[0] || null;
const longevity = ph ? {
  phenoage: num(ph.phenoage), chrono_age: num(ph.chrono_age), delta: num(ph.delta),
  computed: dkey(ph.date),
  // Честно: PhenoAge считается по крови. Сон и стресс за один день туда не попадают —
  // попадает то, что системно меняет воспаление, обмен и картину крови.
  affects_today: [
    { what: 'Насыщенные жиры и сахар', how: 'через воспаление и липиды — попадает в СРБ и обмен', weight: 'да' },
    { what: 'Регулярная нагрузка', how: 'через обмен глюкозы и состав крови', weight: 'да' },
    { what: 'Сон и стресс за один день', how: 'на PhenoAge напрямую не влияют — это про самочувствие', weight: 'нет' },
  ],
} : null;

// =====================================================================
// 6. СПОКОЙНО — что проверено и в норме
// =====================================================================
const quiet = [];
const REF = { 'SpO2_ночь_среднее': [95, 100], 'Дыхание_ночь_среднее': [12, 20] };
for (const [col, [lo, hi]] of Object.entries(REF)) {
  const v = num(last[col]);
  if (v != null && v >= lo && v <= hi) quiet.push(col === 'SpO2_ночь_среднее' ? 'SpO2' : 'дыхание');
}
if (num(last['Пульс_ночной_средний']) != null) {
  const rb = baseline('Пульс_ночной_средний', 30);
  const rv = num(last['Пульс_ночной_средний']);
  if (rb != null && Math.abs(rv - rb) < 3) quiet.push('пульс покоя');
}
if (num(last['Стресс_дневной_средний']) != null) {
  const sb = baseline('Стресс_дневной_средний', 30);
  const sv = num(last['Стресс_дневной_средний']);
  if (sb != null && sv - sb < 6) quiet.push('стресс');
}

const result = {
  updated_at: new Date().toISOString(),
  date: todayISO,
  now_local: hhmm(nowMin),
  data_date: lastDate,
  decision, windows, streaks,
  budget, kcal_today: kcalToday, protein_today: protToday, meals_today: todayMeals.length,
  plan, longevity, quiet,
};

const sd = $getWorkflowStaticData('global');
sd.todayDashboard = result;
return [{ json: result }];

