    ? `Спина: симптом ${daysSinceBack === 0 ? 'сегодня' : daysSinceBack + ' дн назад'} — нагрузку сократить`
    : `Спина: ${daysSinceBack} дн без симптомов`;
  limitNote = 'Грыжа L5/S1: без осевой нагрузки и скручиваний, паузы при сидении каждые 35–40 мин.';
}
const decision = { verdict, note: verdictNote, reasons, caution, limit: limitNote,
  back_last_note: lastBack ? { date: d10(lastBack.Date), category: lastBack.Category || null } : null };

// =====================================================================
// 2. ОКНА ДНЯ
// =====================================================================
// Целевой отбой: если советник дал действие со временем — берём его, иначе 23:30.
function parseActions(txt) {
  const m = String(txt || '').match(/<<<ACTIONS\s*([\s\S]*?)\s*ACTIONS>>>/);
  if (!m) return null;
  try { const o = JSON.parse(m[1].trim()); return (o && Array.isArray(o.actions)) ? o : null; } catch (e) { return null; }
}
const recSorted = recs.filter(r => r.Recommendation_Text && dkey(r.Date) <= todayISO)
  .sort((a, b) => dkey(b.Date).localeCompare(dkey(a.Date)));
const latestRec = recSorted[0] || null;
const latestParsed = latestRec ? parseActions(latestRec.Recommendation_Text) : null;
const latestActions = latestParsed ? latestParsed.actions : [];

let bedMin = 23 * 60 + 30;
for (const a of latestActions) {
  const m = String(a.title || '').match(/(\d{1,2})[:.](\d{2})/);
  if (m && /отбо|спат|лож|сон/i.test(a.title)) { bedMin = (+m[1]) * 60 + (+m[2]); break; }
}
const coffeeMin = bedMin - 8 * 60;   // кофеин: период полувыведения ~5–6 ч
const mealMin   = bedMin - 3 * 60;   // последняя еда за 3 ч до сна

// ВАЖНО: обратный отсчёт здесь НЕ считаем — это кэш, значение протухнет к моменту просмотра.
// Бэкенд отдаёт только целевое время, «сколько осталось» считает браузер при отрисовке.
function windowOf(key, label, targetMin, hint) {
  return { key, label, until: hhmm(targetMin), target_min: targetMin, hint };
}
const windows = [
  windowOf('coffee', 'Последний кофе', coffeeMin, 'за 8 ч до отбоя'),
  windowOf('meal', 'Последняя еда', mealMin, 'за 3 ч до отбоя'),
  windowOf('bed', 'Отбой', bedMin, latestActions.some(a => /отбо|спат/i.test(a.title || '')) ? 'из плана советника' : 'цель по умолчанию'),
];

// серии: сколько ночей подряд сон в целевой зоне 7–9 ч
const SLEEP_MIN_OK = 420, SLEEP_MAX_OK = 540;
let sleepStreak = 0;
for (let i = rows.length - 1; i >= 0; i--) {
  const v = num(rows[i]['Чистый_сон_мин']);
  if (v != null && v >= SLEEP_MIN_OK && v <= SLEEP_MAX_OK) sleepStreak++; else break;
}
const streaks = [];
if (sleepStreak > 0) streaks.push({ label: 'Сон в зоне 7–9 ч', count: sleepStreak, unit: 'ночей' });

// =====================================================================
// 3. БЮДЖЕТ ДНЯ — сколько ещё можно / сколько добрать
// =====================================================================
function parseTargetNum(v) {
  if (v == null) return null;
  const s = String(v).trim();
  if (/^не\s/i.test(s)) return null;
  const m = s.match(/-?\d+(?:[.,]\d+)?/);
  return m ? parseFloat(m[0].replace(',', '.')) : null;
}
const todayMeals = meals.filter(m => m.Date && dkey(m.Date) === todayISO);
function sumCol(col) {
  return todayMeals.reduce((s, m) => s + (num(m[col]) || 0), 0);
}
// что показываем в бюджете: лимиты, которые легко пробить, и цели, которые обычно недобираются
const BUDGET_KEYS = ['Насыщенные жиры', 'Добавленный сахар', 'Натрий', 'Кофеин', 'Клетчатка', 'Витамин D', 'Кальций'];
const budget = [];
for (const t of targets) {
  const name = t['Нутриент'];
  if (!BUDGET_KEYS.includes(name)) continue;
  const col = t['Колонка_в_Meals'];
  if (!col) continue;
  const isLimit = String(t['Категория'] || '').includes('Риск избытка');
  const rda = parseTargetNum(t['Норма_RDA_AI']);
  const ul  = parseTargetNum(t['Верхний_предел_UL']);
  const cap = isLimit ? ul : rda;
  if (!cap) continue;
  const consumed = Math.round(sumCol(col) * 100) / 100;
  const pct = Math.round((consumed / cap) * 100);
  budget.push({
    label: name, unit: t['Единица'] || '', kind: isLimit ? 'limit' : 'goal',
    consumed, cap, pct,
    remaining: Math.round((cap - consumed) * 100) / 100,
    status: isLimit ? (pct > 100 ? 'over' : pct >= 80 ? 'close' : 'ok')
                    : (pct >= 100 ? 'done' : pct >= 60 ? 'partial' : 'low'),
  });
}
budget.sort((a, b) => (a.kind === b.kind ? b.pct - a.pct : a.kind === 'limit' ? -1 : 1));

